SELECT entity_id as quoteId, COUNT(*) as likeCount FROM like_records WHERE entity_id IN
#{entityId}
AND liked = 1 AND entity_type = 0 GROUP BY entity_id

SELECT DATE(created_time) AS stat_date, COUNT(*) AS total_count FROM like_records WHERE entity_id IN
#{id}
AND entity_type = #{entityType} AND liked = 1 AND DATE(created_time) IN
#{date}
GROUP BY DATE(created_time)

SELECT entity_id, COUNT(like_id) AS count
FROM like_records
WHERE entity_type = #{entityType}
AND liked = 1
AND updated_time >= #{startTime}

    AND entity_id IN

        #{entityId}


GROUP BY entity_id

SELECT entity_id, COUNT(like_id) AS count
FROM like_records
WHERE entity_type = #{entityType}
AND liked = 1
AND updated_time >= #{startTime}
GROUP BY entity_id
ORDER BY count DESC, entity_id ASC
LIMIT #{limit}

SELECT entity_id, COUNT(like_id) AS count
FROM like_records
WHERE entity_type = #{entityType}
AND liked = 1
AND updated_time >= #{startTime}
AND updated_time < #{endTime}

    AND entity_id IN

        #{entityId}


GROUP BY entity_id

SELECT entity_id, COUNT(like_id) AS count
FROM like_records
WHERE entity_type = #{entityType}
AND liked = 1
AND updated_time >= #{startTime}
AND updated_time < #{endTime}
